-- =============================================================
-- CarePath Schema — Clean Version
-- MySQL | All issues from review resolved
-- =============================================================
CREATE DATABASE IF NOT EXISTS mindscope
    DEFAULT CHARACTER SET utf8mb4
    DEFAULT COLLATE utf8mb4_unicode_ci;

USE mindscope;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `schools`;
DROP TABLE IF EXISTS `parents`;
DROP TABLE IF EXISTS `counselors`;
DROP TABLE IF EXISTS `students`;
DROP TABLE IF EXISTS `roadmap`;
DROP TABLE IF EXISTS `referrals`;
DROP TABLE IF EXISTS `messages`;
DROP TABLE IF EXISTS `parent_tasks`;
DROP TABLE IF EXISTS `behavior_checks`;
DROP TABLE IF EXISTS `appointment`;
DROP TABLE IF EXISTS `counselor_checkins`;
DROP TABLE IF EXISTS `facility_search_events`;
DROP TABLE IF EXISTS `recommendation_events`;
DROP TABLE IF EXISTS `questionnaire_submissions`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `schools`(
    `schoolid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(255) NOT NULL,
    `location` VARCHAR(255) NOT NULL,
    `district` VARCHAR(255) NOT NULL,
    `student_count` INT NOT NULL,
    `zip_code` VARCHAR(10) NOT NULL
);
CREATE TABLE `parents`(
    `parentid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `fname` TEXT NOT NULL,
    `lname` TEXT NOT NULL,
    `email` TEXT NOT NULL,
    `password` TEXT NOT NULL
);
CREATE TABLE `counselors`(
    `counselorid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `fname` TEXT NOT NULL,
    `lname` TEXT NOT NULL,
    `email` TEXT NOT NULL,
    `schoolid` BIGINT NOT NULL
);
CREATE TABLE `students`(
    `studentid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `fname` TEXT NOT NULL,
    `lname` TEXT NOT NULL,
    `schoolid` BIGINT NOT NULL,
    `parentid` BIGINT NOT NULL,
    `zipcode` VARCHAR(255) NOT NULL
);
CREATE TABLE `roadmap`(
    `roadmapid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `studentid` BIGINT NOT NULL,
    `counselorid` BIGINT NOT NULL,
    `status` ENUM('active', 'paused', 'completed') NOT NULL DEFAULT 'active',
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP());
ALTER TABLE
    `roadmap` ADD UNIQUE `roadmap_studentid_unique`(`studentid`);
CREATE TABLE `referrals`(
    `referralid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `roadmapid` BIGINT NOT NULL,
    `therapy_type` VARCHAR(255) NOT NULL,
    `name` TEXT NOT NULL,
    `location` TEXT NOT NULL,
    `status` ENUM(
        'pending',
        'scheduled',
        'checked_in',
        'completed',
        'missed'
    ) NOT NULL DEFAULT 'pending',
    `met_at` DATETIME NULL
);
CREATE TABLE `parent_tasks`(
    `parent_taskid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `roadmapid` BIGINT NOT NULL,
    `description` TEXT NOT NULL,
    `stage` ENUM(
        'stage_1',
        'stage_2',
        'stage_3',
        'stage_4',
        'stage_5',
        'stage_6'
    ) NOT NULL DEFAULT 'stage_1',
    `status` ENUM(
        'pending',
        'in_progress',
        'completed'
    ) NOT NULL DEFAULT 'pending',
    `visible` BOOLEAN NOT NULL,
    `met_at` DATETIME NULL
);
CREATE TABLE `behavior_checks`(
    `behavior_checkid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `parent_taskid` BIGINT NOT NULL,
    `description` TEXT NOT NULL,
    `stage` INT NOT NULL,
    `status` ENUM('not_met', 'in_progress', 'met') NOT NULL DEFAULT 'not_met',
    `visible` BOOLEAN NOT NULL,
    `met_at` DATETIME NULL
);
CREATE TABLE `appointment`(
    `appointmentid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `parentid` BIGINT NOT NULL,
    `counselorid` BIGINT NOT NULL,
    `createdBy` ENUM('parent', 'counselor') NOT NULL DEFAULT 'parent',
    `status` ENUM('pending', 'confirmed', 'cancelled') NOT NULL DEFAULT 'pending',
    `start` DATETIME NOT NULL,
    `end` DATETIME NOT NULL
);
CREATE TABLE `messages`(
    `messageid` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `appointmentid` BIGINT NOT NULL,
    `message_type` ENUM('parent', 'counselor') NOT NULL,
    `parentid` BIGINT NOT NULL,
    `counselorid` BIGINT NOT NULL,
    `body` TEXT NOT NULL,
    `is_read` BOOLEAN NOT NULL,
    `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE `questionnaire_submissions`(
    `submission_id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `counselor_id` BIGINT NOT NULL,
    `school_id` BIGINT NOT NULL,
    `zip_code` VARCHAR(10) NOT NULL,
    `submitted_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP(), `counselor_form_json` JSON NOT NULL, `parent_form_json` JSON NULL, `pipeline_version` VARCHAR(50) NOT NULL);
CREATE TABLE `recommendation_events`(
    `recommendation_id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `submission_id` BIGINT NOT NULL,
    `school_id` BIGINT NOT NULL,
    `zip_code` VARCHAR(10) NOT NULL,
    `intervention` VARCHAR(255) NOT NULL,
    `therapy_category` VARCHAR(255) NOT NULL,
    `severity` ENUM('critical', 'high', 'moderate') NOT NULL,
    `gap_score` INT NOT NULL,
    `was_gap` BOOLEAN NOT NULL,
    `triggered_by` JSON NOT NULL,
    `recommended_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE `facility_search_events`(
    `search_event_id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `submission_id` BIGINT NOT NULL,
    `zip_code` VARCHAR(10) NOT NULL,
    `therapy_type` VARCHAR(255) NOT NULL,
    `facility_name` TEXT NOT NULL,
    `facility_address` TEXT NULL,
    `source` ENUM('google_places', 'tavily', 'samhsa') NOT NULL,
    `relevance_score` INT NOT NULL,
    `operational_score` INT NOT NULL,
    `total_score` INT NOT NULL,
    `tier` ENUM(
        'recommended',
        'possible',
        'excluded'
    ) NOT NULL,
    `result_type` VARCHAR(50) NOT NULL,
    `was_selected` BOOLEAN NOT NULL,
    `searched_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP());
CREATE TABLE `counselor_checkins`(
    `checkin_id`    BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    `counselor_id`  BIGINT NOT NULL,  -- ref: carepath.counselors.counselorid
    `school_id`     BIGINT NOT NULL,  -- ref: carepath.schools.schoolid
    `checkin_type`  ENUM('post_submission', 'low_usage_prompt') NOT NULL,
    `response`      VARCHAR(255) NOT NULL,
    `submitted_at`  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP()
);
ALTER TABLE
    `facility_search_events` ADD CONSTRAINT `facility_search_events_submission_id_foreign` FOREIGN KEY(`submission_id`) REFERENCES `questionnaire_submissions`(`submission_id`);
ALTER TABLE
    `recommendation_events` ADD CONSTRAINT `recommendation_events_submission_id_foreign` FOREIGN KEY(`submission_id`) REFERENCES `questionnaire_submissions`(`submission_id`);
ALTER TABLE
    `counselors` ADD CONSTRAINT `counselors_schoolid_foreign` FOREIGN KEY(`schoolid`) REFERENCES `schools`(`schoolid`);
ALTER TABLE
    `referrals` ADD CONSTRAINT `referrals_roadmapid_foreign` FOREIGN KEY(`roadmapid`) REFERENCES `roadmap`(`roadmapid`);
ALTER TABLE
    `students` ADD CONSTRAINT `students_parentid_foreign` FOREIGN KEY(`parentid`) REFERENCES `parents`(`parentid`);
ALTER TABLE
    `parent_tasks` ADD CONSTRAINT `parent_tasks_roadmapid_foreign` FOREIGN KEY(`roadmapid`) REFERENCES `roadmap`(`roadmapid`);
ALTER TABLE
    `roadmap` ADD CONSTRAINT `roadmap_counselorid_foreign` FOREIGN KEY(`counselorid`) REFERENCES `counselors`(`counselorid`);
ALTER TABLE
    `appointment` ADD CONSTRAINT `appointment_counselorid_foreign` FOREIGN KEY(`counselorid`) REFERENCES `counselors`(`counselorid`);
ALTER TABLE
    `messages` ADD CONSTRAINT `messages_appointmentid_foreign` FOREIGN KEY(`appointmentid`) REFERENCES `appointment`(`appointmentid`);
ALTER TABLE
    `messages` ADD CONSTRAINT `messages_parentid_foreign` FOREIGN KEY(`parentid`) REFERENCES `parents`(`parentid`);
ALTER TABLE
    `appointment` ADD CONSTRAINT `appointment_parentid_foreign` FOREIGN KEY(`parentid`) REFERENCES `parents`(`parentid`);
ALTER TABLE
    `students` ADD CONSTRAINT `students_studentid_foreign` FOREIGN KEY(`studentid`) REFERENCES `roadmap`(`studentid`);
ALTER TABLE
    `students` ADD CONSTRAINT `students_schoolid_foreign` FOREIGN KEY(`schoolid`) REFERENCES `schools`(`schoolid`);
ALTER TABLE
    `messages` ADD CONSTRAINT `messages_counselorid_foreign` FOREIGN KEY(`counselorid`) REFERENCES `counselors`(`counselorid`);
ALTER TABLE
    `behavior_checks` ADD CONSTRAINT `behavior_checks_parent_taskid_foreign` FOREIGN KEY(`parent_taskid`) REFERENCES `parent_tasks`(`parent_taskid`);














